/*
 | Адреса каталога.
 |
 | Сайт отдаётся страницами, а не JSON: адрес — это готовая страница,
 | и фронтенд забирает её как документ, чтобы подменить часть разметки.
 | Список держим типом, чтобы адреса не расползались по компонентам.
 */

interface IShopApiGet {
    /**
     * Каталог. Фильтры и «показать ещё» передаются строкой запроса.
     */
    '/shop.html': (query?: IShopFilters) => Document;

    /**
     * Страница товара: цвет — это отдельный адрес.
     */
    [key: `/shop/${TProductSlug}.html`]: () => Document;
}
